package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class CatalogueWorkflowsBrowserAcceptance {
 static void add(Page page,String name,String group){var form=page.locator("#add-step");form.getByLabel("Step summary").fill(name);form.getByLabel("Team instructions").fill("Internal handling for "+name);form.getByLabel("Responsible team").selectOption(group);form.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Add step").setExact(true)).press("Enter");}
 static void run(BrowserTest h)throws Exception{
  String offering;var groups=new ArrayList<String>();try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String user:List.of("CatalogPlanBuyer","CatalogPlanFirst","CatalogPlanSecond"))Service.createAccount(db,map("name",user,"password",WorkflowSupport.PASSWORD,"role",user.equals("CatalogPlanBuyer")?"requester":"agent"));for(String user:List.of("CatalogPlanFirst","CatalogPlanSecond")){String group=Service.create(db,"sys_user_group",map("short_description",user.equals("CatalogPlanFirst")?"Equipment preparation":"Delivery team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,RecordAccess.owner(db,user));groups.add(group);}offering=Catalogue.save(db,db.viewerId,"",CatalogueAcceptance.offering("New workspace equipment",0,true)).get("offering_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var admin=browser.newContext();var buyer=browser.newContext();var first=browser.newContext();var second=browser.newContext()){
   var page=admin.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/catalogue/"+offering);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Configure team workflow")).press("Enter");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Enable workflow"))).isDisabled();add(page,"Prepare equipment <script>",groups.get(0));add(page,"Deliver equipment",groups.get(1));add(page,"Temporary duplicate",groups.get(1));page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Remove step: Temporary duplicate").setExact(true)).press("Enter");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Move earlier: Deliver equipment").setExact(true)).press("Enter");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Move later: Deliver equipment").setExact(true)).press("Enter");var step=page.locator("section[id^='step-']").first();step.getByLabel("Team instructions").fill("Internal: prepare and inspect equipment");step.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Save step")).press("Enter");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Enable workflow")).press("Enter");assertThat(page.locator("main")).containsText("Enabled for new orders");assertThat(page.locator("main script")).hasCount(0);
   for(String theme:List.of("light","dark")){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/catalogue-workflow-"+theme+".png")).setFullPage(true));}
   var request=buyer.newPage();request.navigate(h.base()+"/login");request.getByLabel("Username",new Page.GetByLabelOptions().setExact(true)).fill("CatalogPlanBuyer");request.getByLabel("Password",new Page.GetByLabelOptions().setExact(true)).fill(WorkflowSupport.PASSWORD);request.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Enter your workspace")).click();request.waitForURL("**/requests");request.navigate(h.base()+"/catalogue/"+offering);request.getByLabel("Request details").fill("Deliver to the shared office");request.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Submit service request")).press("Enter");assertThat(request.locator("#catalogue-progress")).containsText("0 of 2 steps completed");assertFalse(request.locator("main").textContent().contains("Internal: prepare"));String parent=request.url().substring(request.url().lastIndexOf('/')+1);List<Map<String,Object>> tasks;try(var db=h.store.open()){tasks=db.all("SELECT task_id FROM os_case_task WHERE parent_id=? ORDER BY ordinal",parent);}
   var worker=first.newPage();h.login(worker,"CatalogPlanFirst");worker.navigate(h.base()+"/record/sc_request/"+parent+"/work-tasks");var task=worker.locator("#task-"+tasks.get(0).get("task_id"));task.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");task.getByLabel("Completion outcome").fill("Equipment inspected and ready");task.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");request.reload();assertThat(request.locator("#catalogue-progress")).containsText("1 of 2 steps completed");
   worker=second.newPage();h.login(worker,"CatalogPlanSecond");worker.navigate(h.base()+"/record/sc_request/"+parent+"/work-tasks");task=worker.locator("#task-"+tasks.get(1).get("task_id"));task.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");task.getByLabel("Completion outcome").fill("Delivered and received");task.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");request.reload();assertThat(request.locator("#catalogue-progress")).containsText("2 of 2 steps completed");assertThat(request.locator(".page-heading .pill")).hasText("Complete");ReleaseBrowserAcceptance.accessible(request);request.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/catalogue-progress-light.png")).setFullPage(true));request.navigate(h.base()+"/catalogue/"+offering);request.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Submit service request")).press("Enter");assertThat(request.locator("#catalogue-progress")).containsText("0 of 2 steps completed");String recovery=request.url().substring(request.url().lastIndexOf('/')+1);List<Map<String,Object>> recoveryTasks;try(var db=h.store.open()){recoveryTasks=db.all("SELECT task_id FROM os_case_task WHERE parent_id=? ORDER BY ordinal",recovery);}page.navigate(h.base()+"/record/sc_request/"+recovery+"/work-tasks");for(var row:recoveryTasks){var block=page.locator("#task-"+row.get("task_id"));block.getByLabel("Cancellation reason").fill("Alternative arrangement");block.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Cancel task").setExact(true)).press("Enter");block.getByLabel("Requirement waiver reason").fill("Alternative delivery reviewed");block.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Waive task requirement")).press("Enter");}page.navigate(h.base()+"/record/sc_request/"+recovery);for(int n=0;n<2;n++)page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Advance fulfilment")).press("Enter");assertThat(page.locator(".page-heading .pill")).hasText("Complete");page.navigate(h.base()+"/admin/catalogue/"+offering+"/workflow");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Disable workflow")).press("Enter");assertThat(page.locator("main")).containsText("Disabled. New orders");
  }
 }
}
